    "totalInTopic": 7,
    "title": "Make it faster, not magically larger",
    "summary": "Why can a powder react faster than a lump of the same material and mass? More surface is exposed to the other reactant, so more particles can",
    "startSec": 627.8,
    "endSec": 769.96,
    "durationSec": 142.16,
    "src": "/reallife-videos-astra/chemical-reactions-part-00.mp4",
    "parts": [
      {
        "src": "/reallife-videos-astra/chemical-reactions-part-00.mp4",
        "start": 0.0,
        "duration": 280.08
      },
      {
        "src": "/reallife-videos-astra/chemical-reactions-part-01.mp4",
        "start": 280.08,
        "duration": 280.0
      },
      {
        "src": "/reallife-videos-astra/chemical-reactions-part-02.mp4",
        "start": 560.08,
        "duration": 209.88
      }
    ],
    "poster": "/reallife-videos-astra/chemical-reactions.jpg",
    "captions": [
      {
        "t": 628.09,
        "who": "",
        "text": "Why can a powder react faster than a lump of the same material and mass?"
      },
      {
        "t": 632.92,
        "who": "",
        "text": "More surface is exposed to the other reactant, so more particles can"
      },
      {
        "t": 637.01,
        "who": "",
        "text": "collide at the surface, not because powder contains more atoms overall."
      },
      {
        "t": 642.06,
        "who": "",
        "text": "Exactly."
      },
      {
        "t": 643.25,
        "who": "",
        "text": "Rate measures how quickly reactants are used or products form."
      },
      {
        "t": 647.1,
        "who": "",
        "text": "We might measure a gas volume per unit time or track mass change"
      },
      {
        "t": 650.89,
        "who": "",
        "text": "in suitable supervised apparatus."
      },
      {
        "t": 653.68,
        "who": "",
        "text": "Do particles react every time they bump into each other?"
      },
      {
        "t": 657.55,
        "who": "",
        "text": "No."
      },
      {
        "t": 658.45,
        "who": "",
        "text": "Collisions need enough energy and a suitable arrangement."
      },
      {
        "t": 662.24,
        "who": "",
        "text": "Raising temperature increases particle energy, so more collisions can"
      },
      {
        "t": 666.33,
        "who": "",
        "text": "overcome the reaction's energy barrier."
      },
      {
        "t": 668.71,
        "who": "",
        "text": "Higher concentration often increases collision frequency when"
      },
      {
        "t": 672.31,
        "who": "",
        "text": "other conditions are comparable."
      },
      {
        "t": 674.64,
        "who": "",
        "text": "For a fair comparison, change one factor and control the others, such as"
      },
      {
        "t": 679.05,
        "who": "",
        "text": "mass, temperature, and solution volume."
      },
      {
        "t": 681.92,
        "who": "",
        "text": "Repeat measurements too."
      },
      {
        "t": 683.86,
        "who": "",
        "text": "Good."
      },
      {
        "t": 684.76,
        "who": "",
        "text": "A catalyst offers an alternative pathway with a lower energy barrier."
      },
      {
        "t": 688.9,
        "who": "",
        "text": "It is not consumed overall by the reaction."
      }
    ]
