    "episodeTitle": "Magnetism & Electricity",
    "index": 1,
    "totalInTopic": 8,
    "title": "The magnet that refuses to be half a magnet",
    "summary": "Mia, will our magnet attract every metal on this tray? I was going to say yes, but",
    "startSec": 0.0,
    "endSec": 83.48,
    "durationSec": 83.48,
    "src": "/reallife-videos-astra/magnetism-electricity-part-00.mp4",
