      {
        "t": 529.81,
        "who": "",
        "text": "A 10 newton force acts with a perpendicular distance of"
      },
      {
        "t": 532.7,
        "who": "",
        "text": "half a meter from a pivot."
      },
      {
        "t": 534.44,
        "who": "",
        "text": "What is its moment?"
      },
      {
        "t": 536.3,
        "who": "",
        "text": "Force times perpendicular distance, five newton meters."
      },
      {
        "t": 540.61,
        "who": "",
        "text": "I must use the shortest perpendicular distance from the pivot to"
      },
      {
        "t": 543.93,
        "who": "",
        "text": "the force's line of action."
      },
      {
        "t": 546.12,
        "who": "",
        "text": "Exactly."
      },
      {
        "t": 547.18,
        "who": "",
        "text": "A smaller force farther from the pivot can produce a larger"
      },
      {
        "t": 550.4,
        "who": "",
        "text": "moment than a bigger force nearby."
      },
      {
        "t": 552.87,
        "who": "",
        "text": "Door handles are placed away from hinges for a reason."
      },
      {
        "t": 556.44,
        "who": "",
        "text": "A 20 newton force half a meter to one side can balance 10 newtons"
      },
      {
        "t": 560.08,
        "who": "",
        "text": "A 20 newton force half a meter to one side can balance 10 newtons"
      },
      {
        "t": 560.95,
        "who": "",
        "text": "one meter to the other side."
      },
      {
        "t": 562.73,
        "who": "",
        "text": "Both moments are 10 newton meters in opposite directions."
      },
      {
        "t": 566.84,
        "who": "",
        "text": "Good."
      },
      {
        "t": 567.56,
        "who": "",
        "text": "Rotational equilibrium requires balanced moments."
      },
      {
        "t": 570.73,
        "who": "",
        "text": "Full static equilibrium also requires zero resultant force."
      },
      {
        "t": 575.11,
        "who": "",
        "text": "The pivot's support force must be included when checking the vertical forces."
      },
      {
        "t": 579.68,
        "who": "",
        "text": "Finally, pressure is force divided by area."
      },
      {
        "t": 582.92,
        "who": "",
        "text": "200 newtons acts over 0.02"
      }
